{
  "candidate_edge_types": [
    {
      "name": "IDENTIFIES_TRANSFORMATION_WEAKNESS_FROM_OBSERVATION",
      "definition": "An agent recognizes a specific weakness or discrepancy in the target transformation/filter implementation or behavior that could be exploited to bypass it.",
      "source_description": "An observation of the target transformation/filter implementation or execution behavior that reveals how content is processed.",
      "target_description": "The agent's conclusion identifying a specific exploitable weakness or discrepancy in that transformation."
    },
    {
      "name": "DESIGNS_CANDIDATE_TO_EVADE_TRANSFORMATION",
      "definition": "An agent creates a candidate artifact specifically constructed to evade the target transformation/filter based on previously observed filtering logic or behavior.",
      "source_description": "An earlier observation of the target transformation/filter logic or its effect on content.",
      "target_description": "A subsequent agent action that creates a candidate artifact intended to bypass the transformation."
    },
    {
      "name": "VERIFIES_CANDIDATE_BY_APPLYING_TRANSFORMATION",
      "definition": "An agent subjects a candidate artifact to the target transformation/filter and inspects the resulting output to evaluate whether the candidate survives and remains effective.",
      "source_description": "A candidate artifact produced by the agent.",
      "target_description": "The subsequent action and observation of applying the target transformation to the candidate and inspecting the transformed output."
    },
    {
      "name": "REVISES_CANDIDATE_AFTER_FAILED_TRANSFORMATION",
      "definition": "After observing that a candidate artifact was removed, escaped, or otherwise neutralized by the target transformation, the agent creates a modified candidate intended to overcome the observed failure.",
      "source_description": "An observation that a candidate artifact failed under the target transformation.",
      "target_description": "A subsequent agent action that creates a revised candidate artifact intended to overcome the observed failure."
    },
    {
      "name": "ACCEPTS_CANDIDATE_AFTER_SUCCESSFUL_TRANSFORMATION",
      "definition": "An observed transformation result shows that a candidate artifact retains the required effective content, leading the agent to accept and finalize the candidate as a viable solution.",
      "source_description": "An observation of successful survival of a candidate through the target transformation.",
      "target_description": "Subsequent agent decision or action to finalize, deploy, or submit the candidate solution."
    },
    {
      "name": "DERIVES_SUCCESS_CRITERIA_FROM_VERIFICATION_SCRIPT",
      "definition": "An agent inspects a test or verification script to determine the conditions for task success and uses that understanding to guide subsequent solution construction.",
      "source_description": "An observation of a verification/test script that defines how the solution will be judged.",
      "target_description": "Subsequent agent action or strategy aimed at satisfying the identified success criteria."
    }
  ]
}

